function badgeStyle(kind: "ok" | "warn" | "bad" | "neutral"): CSSProperties {
  const base: CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: 34,
    padding: "0 12px",
    borderRadius: 8,
    fontSize: 13,
    fontWeight: 900,
    letterSpacing: 0.2,
    border: "1px solid rgba(0,0,0,0.28)",
    boxShadow: "inset 0 1px 0 rgba(255,255,255,0.18)",
    whiteSpace: "nowrap",
  };

  if (kind === "ok") {
    return {
      ...base,
      color: "#fff",
      background: "linear-gradient(180deg, #1ea34a 0%, #157736 100%)",
    };
  }

  if (kind === "warn") {
    return {
      ...base,
      color: "#fff",
      background: "linear-gradient(180deg, #9e6b06 0%, #6f4900 100%)",
    };
  }

  if (kind === "bad") {
    return {
      ...base,
      color: "#fff",
      background: "linear-gradient(180deg, #b21d1d 0%, #7f1111 100%)",
    };
  }

  return {
    ...base,
    color: "#fff",
    background: "linear-gradient(180deg, #5a606b 0%, #3d434d 100%)",
  };
}

