function statusFromBool(ok: boolean, good: string, bad: string) {
  return ok ? good : bad;
}

function firstFilled(...values: any[]) {
  for (const v of values) {
    if (!isEmptyValue(v)) return v;
  }
  return null;
}

function getExtraValue(extra: any, keys: string[]) {
  const obj = safeJson(extra);
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;

  for (const [rawKey, rawValue] of Object.entries(obj)) {
    const nk = norm(rawKey).replace(/[_-]/g, " ");
    for (const wanted of keys) {
      const nw = norm(wanted).replace(/[_-]/g, " ");
      if (nk === nw || nk.includes(nw) || nw.includes(nk)) {
        return rawValue;
      }
    }
  }

  return null;
}

function valueToLines(value: any): string[] {
  const parsed = safeJson(value);
  if (parsed == null) return [];

  if (Array.isArray(parsed)) {
    return parsed
      .flatMap((item) => {
        if (item == null) return [];
        if (typeof item === "string") return [item];
        if (typeof item === "object") {
          return [JSON.stringify(item)];
        }
        return [String(item)];
      })
      .filter(Boolean);
  }

  if (typeof parsed === "string") {
    return parsed
      .split(/\n+/)
      .map((x) => x.trim())
      .filter(Boolean);
  }

  if (typeof parsed === "object") {
    return Object.entries(parsed).map(([k, v]) =>
      `${k}: ${typeof v === "string" ? v : JSON.stringify(v)}`
    );
  }

  return [String(parsed)];
}

function prettifyKey(key: string) {
  return String(key ?? "")
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function formatCellValue(v: any): ReactNode {
  if (v == null || v === "") return "—";
  if (typeof v === "boolean") return v ? "Ja" : "Nee";
  if (typeof v === "object") {
    return (
      <pre
        className="whitespace-pre-wrap break-words text-[12px] leading-5 font-bold"
        style={{ margin: 0, fontFamily: "inherit" }}
      >
        {JSON.stringify(v, null, 2)}
      </pre>
    );
  }
  return String(v);
}

