function UitslagenTable({
  rows,
}: {
  rows: AnyRow[];
}) {
  const columns = useMemo(() => {
    const preferred = [
      "datum",
      "evenement",
      "organisatie",
      "tegenstander",
      "uitslag",
      "resultaat",
      "wijze",
      "discipline",
      "klasse",
      "gewicht",
      "locatie",
    ];

    const keySet = new Set<string>();
    for (const row of rows) {
      Object.keys(row ?? {}).forEach((k) => {
        if (!["id", "created_at", "updated_at", "matchmaking_id"].includes(k)) {
          keySet.add(k);
        }
      });
    }

    const all = Array.from(keySet);
    const ordered = [
      ...preferred.filter((k) => keySet.has(k)),
      ...all.filter((k) => !preferred.includes(k)),
    ];

    return ordered;
  }, [rows]);

  return (
    <div style={darkCardShellStyle()}>
      <div style={darkHeaderStyle()}>
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <span
              className="inline-block h-5 w-5 rounded-[4px]"
              style={{ background: NVB_ORANGE }}
            />
            <div className="text-[18px] font-black uppercase tracking-[0.06em]">
              Uitslagen
            </div>
          </div>
          <div className="text-sm font-black text-white/75">{rows.length} stuks</div>
        </div>
      </div>

      <div style={darkSectionBodyStyle()}>
        {rows.length === 0 ? (
          <div className="text-sm font-bold text-white/72">
            Geen uitslagen gevonden in matchmaker_uitslagen_raw.
          </div>
        ) : (
          <div
            className="overflow-x-auto rounded-[14px]"
            style={{ border: "2px solid rgba(255,255,255,0.08)" }}
          >
            <table className="min-w-full text-sm">
              <thead>
                <tr style={tableHeaderStyle()}>
                  {columns.map((col) => (
                    <th
                      key={col}
                      className="px-4 py-3 text-left font-black whitespace-nowrap"
                    >
                      {prettifyKey(col)}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.map((row, idx) => (
                  <tr key={row.id ?? idx} style={zebraDarkRowStyle(idx)}>
                    {columns.map((col) => (
                      <td
                        key={col}
                        className="px-4 py-3 align-top font-extrabold break-words"
                      >
                        {formatCellValue(row[col])}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export default function MatchmakerFighterContextPage() {
  const router = useRouter();
  const params = useParams<{
    matchmakingId: string;
    fighterContextId: string;
  }>();

  const matchmakingId = String(params?.matchmakingId ?? "");
  const fighterContextId = String(params?.fighterContextId ?? "");

  const [row, setRow] = useState<FighterContext | null>(null);
  const [uitslagenRows, setUitslagenRows] = useState<AnyRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function fetchFighterRow() {
      if (isUuidLike(fighterContextId)) {
        const res = await supabase
          .from("matchmaker_fighter_context")
          .select("*")
          .eq("matchmaking_id", matchmakingId)
          .eq("inschrijving_id", fighterContextId)
          .limit(1)
          .maybeSingle();

        return res;
      }

      const fighterRowNr = Number(fighterContextId);

      if (!Number.isFinite(fighterRowNr)) {
        throw new Error("Ongeldige fighter id.");
      }

      return await supabase
        .from("matchmaker_fighter_context")
        .select("*")
        .eq("matchmaking_id", matchmakingId)
        .eq("row_nr", fighterRowNr)
        .limit(1)
        .maybeSingle();
    }

    async function fetchUitslagenForFighter(fighter: FighterContext) {
      const { data, error } = await supabase
        .from("matchmaker_uitslagen_raw")
        .select("*")
        .eq("matchmaking_id", matchmakingId);

      if (error) {
        console.error("[fighter-context] uitslagen query fout", error);
        return [];
      }

      const rows = (data ?? []) as AnyRow[];
      if (!rows.length) return [];

      const va = String(fighter.va_nummer ?? "").trim();
      const fullName = norm(
        [fighter.voornaam, fighter.achternaam].filter(Boolean).join(" ")
      );
      const inputName = norm(fighter.naam_input);
      const fpName = norm(fighter.fp_naam);
      const dobInput = String(fighter.geboortedatum_input ?? "").trim();
      const dobFp = String(fighter.fp_geboortedatum ?? "").trim();

      const filtered = rows.filter((r) => {
        const rowVaCandidates = [
          r.va_nummer,
          r.va,
          r.fp_nummer,
          r.fighter_va,
          r.vechter_va,
          r.licentie_nummer,
        ]
          .map((x) => String(x ?? "").trim())
          .filter(Boolean);

        if (va && rowVaCandidates.includes(va)) return true;

        const rowName = norm(
          firstFilled(
            r.naam,
            r.naam_vechter,
            r.vechter_naam,
            r.fighter_name,
            r.fp_naam,
            [r.voornaam, r.achternaam].filter(Boolean).join(" ")
          )
        );

        const rowDob = String(
          firstFilled(
            r.geboortedatum,
            r.geb_datum,
            r.fp_geboortedatum,
            r.dob
          ) ?? ""
        ).trim();

        const nameMatches =
          !!rowName &&
          [fullName, inputName, fpName].filter(Boolean).some((candidate) => {
            return (
              rowName === candidate ||
              rowName.includes(candidate) ||
              candidate.includes(rowName)
            );
          });

        const dobMatches =
          !!rowDob &&
          [dobInput, dobFp].filter(Boolean).some((candidate) => rowDob === candidate);

        return nameMatches || (nameMatches && dobMatches);
      });

      const withDateSort = [...filtered].sort((a, b) => {
        const da = new Date(
          firstFilled(a.datum, a.partij_datum, a.event_datum, a.created_at) ?? 0
        ).getTime();
        const db = new Date(
          firstFilled(b.datum, b.partij_datum, b.event_datum, b.created_at) ?? 0
        ).getTime();
        return db - da;
      });

      return withDateSort;
    }

    async function run() {
      try {
        setLoading(true);
        setErr(null);
        setRow(null);
        setUitslagenRows([]);

        if (!matchmakingId) {
          throw new Error("Geen matchmakingId in route.");
        }

        if (!fighterContextId) {
          throw new Error("Geen fighterContextId in route.");
        }

        const fighterRes = await fetchFighterRow();

        if (fighterRes.error) {
          throw new Error(fighterRes.error.message);
        }

        if (!fighterRes.data) {
          throw new Error("Geen vechter gevonden binnen deze matchmaking.");
        }

        const fighter = fighterRes.data as FighterContext;
        const uitslagen = await fetchUitslagenForFighter(fighter);

        if (cancelled) return;

        setRow(fighter);
        setUitslagenRows(uitslagen);
      } catch (e: any) {
        if (cancelled) return;
        setErr(e?.message ?? "Onbekende fout.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    run();

    return () => {
      cancelled = true;
    };
  }, [matchmakingId, fighterContextId]);

  const extraParsed = useMemo(() => safeJson(row?.extra), [row?.extra]);

  const fullName = useMemo(() => {
    if (!row) return "ONBEKENDE VECHTER";
    const v = String(row.voornaam ?? "").trim();
    const a = String(row.achternaam ?? "").trim();
    if (v || a) return `${v} ${a}`.trim();
    const ni = String(row.naam_input ?? "").trim();
    return ni || "ONBEKENDE VECHTER";
  }, [row]);

  const recordStr = useMemo(() => {
    if (!row) return "—";
    if (
      row.record_w == null &&
      row.record_l == null &&
      row.record_d == null
    ) {
      return "—";
    }
    return `${row.record_w ?? 0} - ${row.record_l ?? 0} - ${row.record_d ?? 0}`;
  }, [row]);

  const naamMatch = !!row?.naam_match;
  const dobMatch = !!row?.geboortedatum_match;
  const gymMatch = !!row?.gym_match;
  const keurmerk = asYes(row?.heeft_keurmerk);

  const licentieRaw = useMemo(
    () =>
      firstFilled(
        getExtraValue(extraParsed, ["licentie", "licentie geldig", "heeft licentie"]),
        getExtraValue(extraParsed, ["license", "license valid"])
      ),
    [extraParsed]
  );

  const licentieJaNee = useMemo(() => {
    if (licentieRaw == null) return "—";
    return asYes(licentieRaw) ? "Ja" : "Nee";
  }, [licentieRaw]);

  const startVerbodRaw = useMemo(
    () =>
      firstFilled(
        getExtraValue(extraParsed, ["start verbod", "startverbod", "start verbod tot"]),
        getExtraValue(extraParsed, ["schorsing", "suspensie", "suspension"])
      ),
    [extraParsed]
  );

  const startVerbodText = useMemo(() => {
    if (isEmptyValue(startVerbodRaw)) return "Nee";
    if (typeof startVerbodRaw === "boolean") return startVerbodRaw ? "Ja" : "Nee";
    const s = String(startVerbodRaw).trim();
    if (!s) return "Nee";
    if (["false", "0", "nee", "no"].includes(s.toLowerCase())) return "Nee";
    if (["true", "1", "ja", "yes"].includes(s.toLowerCase())) return "Ja";
    return s;
  }, [startVerbodRaw]);

  const keurmerkInfo = useMemo(() => {
    const keurmerkObj = safeJson(
      firstFilled(
        getExtraValue(extraParsed, ["keurmerk"]),
        getExtraValue(extraParsed, ["keurmerk info"]),
        getExtraValue(extraParsed, ["keurmerk_reason"]),
        getExtraValue(extraParsed, ["keurmerk reason"])
      )
    );

    const reason =
      firstFilled(
        getExtraValue(extraParsed, ["keurmerk_reason"]),
        (keurmerkObj && typeof keurmerkObj === "object" && !Array.isArray(keurmerkObj)
          ? keurmerkObj.reason
          : null)
      ) ?? null;

    const matchedGym =
      keurmerkObj && typeof keurmerkObj === "object" && !Array.isArray(keurmerkObj)
        ? firstFilled(
            keurmerkObj.sportschool_match?.naam,
            keurmerkObj.sportschool_match?.plaats,
            keurmerkObj.bron_gym,
            keurmerkObj.naam
          )
        : null;

    const bronGym =
      keurmerkObj && typeof keurmerkObj === "object" && !Array.isArray(keurmerkObj)
        ? firstFilled(keurmerkObj.bron_gym, keurmerkObj.gym, keurmerkObj["bron gym"])
        : null;

    return {
      raw: keurmerkObj,
      reason: reason ? String(reason) : null,
      matchedGym: matchedGym ? String(matchedGym) : null,
      bronGym: bronGym ? String(bronGym) : null,
    };
  }, [extraParsed]);

  const meldingLines = useMemo(() => {
    const lines: string[] = [];

    if (!naamMatch) {
      lines.push(
        `Naam wijkt af: input "${row?.naam_input ?? "—"}" ↔ FightPassport "${row?.fp_naam ?? "—"}".`
      );
    }

    if (!dobMatch) {
      lines.push(
        `Geboortedatum wijkt af: input "${row?.geboortedatum_input ? fmtDate(row.geboortedatum_input) : "—"}" ↔ FightPassport "${row?.fp_geboortedatum ? fmtDate(row.fp_geboortedatum) : "—"}".`
      );
    }

    if (!gymMatch) {
      lines.push(
        `Gym wijkt af: input "${row?.gym_input ?? "—"}" ↔ FightPassport "${row?.fp_gym ?? "—"}".`
      );
    }

    if (keurmerkInfo.bronGym) {
      lines.push(`Keurmerk bron gym: ${keurmerkInfo.bronGym}.`);
    }

    if (keurmerkInfo.matchedGym) {
      lines.push(`Gematcht met sportschool uit DB: ${keurmerkInfo.matchedGym}.`);
    }

    if (keurmerkInfo.reason) {
      lines.push(keurmerkInfo.reason);
    } else {
      lines.push(
        keurmerk
          ? "Gym heeft een geldig keurmerk."
          : "Geen geldig keurmerk gevonden of geen keurmerkdata beschikbaar."
      );
    }

    lines.push(
      `Invoer matchmaker: naam "${row?.naam_input ?? "—"}", gym "${row?.gym_input ?? "—"}", geboortedatum "${row?.geboortedatum_input ? fmtDate(row.geboortedatum_input) : "—"}".`
    );

    lines.push(
      `FightPassport gevonden: naam "${row?.fp_naam ?? "—"}", gym "${row?.fp_gym ?? "—"}", geboortedatum "${row?.fp_geboortedatum ? fmtDate(row.fp_geboortedatum) : "—"}".`
    );

    const extraMeldingen = valueToLines(
      firstFilled(
        extraParsed?.meldingen,
        getExtraValue(extraParsed, ["meldingen"]),
        getExtraValue(extraParsed, ["warnings"]),
        getExtraValue(extraParsed, ["waarschuwingen"])
      )
    );

    for (const line of extraMeldingen) {
      if (!lines.includes(line)) lines.push(line);
    }

    return lines.filter(Boolean);
  }, [
    row,
    naamMatch,
    dobMatch,
    gymMatch,
    keurmerk,
    keurmerkInfo,
    extraParsed,
  ]);

  const verschillenLines = useMemo(() => {
    const lines = valueToLines(
      firstFilled(
        extraParsed?.verschillen,
        getExtraValue(extraParsed, ["verschillen"]),
        getExtraValue(extraParsed, ["differences"])
      )
    );

    if (!naamMatch && !lines.some((x) => norm(x).includes("naam"))) {
      lines.unshift("Naam mismatch tussen input en FightPassport.");
    }
    if (!dobMatch && !lines.some((x) => norm(x).includes("geboortedatum"))) {
      lines.push("Geboortedatum mismatch tussen input en FightPassport.");
    }
    if (!gymMatch && !lines.some((x) => norm(x).includes("gym"))) {
      lines.push("Gym mismatch tussen input en FightPassport.");
    }

    return lines.filter(Boolean);
  }, [extraParsed, naamMatch, dobMatch, gymMatch]);

  const cleanedExtraRows = useMemo(() => {
    if (!extraParsed || typeof extraParsed !== "object" || Array.isArray(extraParsed)) {
      return [];
    }

    const skipKeys = new Set([
      "meldingen",
      "verschillen",
      "keurmerk",
      "keurmerk_reason",
      "licentie",
      "licentie_geldig",
      "license",
      "startverbod",
      "start_verbod",
      "start verbod",
      "naam_match",
      "geboortedatum_match",
      "gym_match",
      "fp_naam",
      "fp_gym",
      "fp_geboortedatum",
      "fp_klasse",
      "record_w",
      "record_l",
      "record_d",
      "uitslagen_count",
      "laatste_partij_datum",
      "nulmeting_opmerking",
    ]);

    return Object.entries(extraParsed)
      .filter(([k, v]) => {
        if (skipKeys.has(k)) return false;
        if (isEmptyValue(v)) return false;
        return true;
      })
      .map(([k, v]) => ({
        key: prettifyKey(k),
        value: v,
      }));
  }, [extraParsed]);

  return (
    <div className={inter.className} style={pageShellStyle()}>
      <div className="mx-auto max-w-[1800px] px-4 py-6">
        <div style={outerFrameStyle()}>
          <div style={innerPlateStyle()}>
            <div style={heroStyle()}>
              <div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
                <div className="min-w-0">
                  <div className="text-sm font-black uppercase tracking-[0.18em] text-white/65">
                    Fighter context
                  </div>

                  <div
                    className={`${bebas.className} mt-1 text-[42px] leading-none tracking-[0.14em] md:text-[64px]`}
                    style={fightSupportTitleText()}
                  >
                    FIGHTSUPPORT
                  </div>

                  <div className="mt-2 text-sm font-black uppercase tracking-[0.28em] text-white/55">
                    Fighter dashboard
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 xl:min-w-[680px]">
                  <div>
                    <div className="text-xs font-black uppercase tracking-[0.14em] text-white/55">
                      Matchmaking ID
                    </div>
                    <div className="mt-1 text-sm font-black text-white/90 break-all">
                      {matchmakingId || "—"}
                    </div>
                  </div>

                  <div>
                    <div className="text-xs font-black uppercase tracking-[0.14em] text-white/55">
                      Fighter ref
                    </div>
                    <div className="mt-1 text-sm font-black text-white/90 break-all">
                      {fighterContextId || "—"}
                    </div>
                  </div>

                  <div>
                    <div className="text-xs font-black uppercase tracking-[0.14em] text-white/55">
                      Status
                    </div>
                    <div className="mt-2">
                      <span
                        style={badgeStyle(err ? "bad" : loading ? "warn" : "ok")}
                      >
                        {err ? "FOUT" : loading ? "LADEN" : "KLAAR"}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-end gap-2 justify-start xl:justify-end">
                    <button
                      onClick={() => router.back()}
                      className="h-[50px] min-w-[58px] rounded-[8px] px-4 text-lg font-black text-white active:scale-[0.98]"
                      style={{
                        background:
                          "linear-gradient(180deg, #ff6a00 0%, #e14b00 100%)",
                        border: "1px solid rgba(0,0,0,0.45)",
                        boxShadow:
                          "0 10px 20px rgba(0,0,0,0.28), inset 0 1px 0 rgba(255,255,255,0.20)",
                      }}
                      title="Terug"
                    >
                      ←
                    </button>

                    <button
                      onClick={() => window.location.reload()}
                      className="h-[50px] min-w-[58px] rounded-[8px] px-4 text-lg font-black text-zinc-900 active:scale-[0.98]"
                      style={{
                        background:
                          "linear-gradient(180deg, #d7d7d7 0%, #8f8f8f 100%)",
                        border: "1px solid rgba(0,0,0,0.45)",
                        boxShadow:
                          "0 10px 20px rgba(0,0,0,0.24), inset 0 1px 0 rgba(255,255,255,0.42)",
                      }}
                      title="Vernieuwen"
                    >
                      ↻
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {loading ? (
              <div className="mt-5" style={steelCardStyle()}>
                <div style={darkHeaderStyle()}>
                  <div className="text-lg font-black uppercase tracking-[0.06em]">
                    Laden
                  </div>
                </div>
                <div style={sectionBodyStyle()}>
                  <div className="text-sm font-bold text-zinc-800">
                    Gegevens worden opgehaald…
                  </div>
                </div>
              </div>
            ) : err ? (
              <div className="mt-5" style={steelCardStyle()}>
                <div style={darkHeaderStyle(RED)}>
                  <div className="text-lg font-black uppercase tracking-[0.06em]">
                    Fout
                  </div>
                </div>
                <div style={sectionBodyStyle()}>
                  <div className="text-sm font-bold text-zinc-800">{err}</div>
                </div>
              </div>
            ) : !row ? (
              <div className="mt-5" style={steelCardStyle()}>
                <div style={darkHeaderStyle()}>
                  <div className="text-lg font-black uppercase tracking-[0.06em]">
                    Geen data
                  </div>
                </div>
                <div style={sectionBodyStyle()}>
                  <div className="text-sm font-bold text-zinc-800">
                    Geen data gevonden in matchmaker_fighter_context.
                  </div>
                </div>
              </div>
            ) : (
              <>
                <div className="mt-6 grid grid-cols-1 gap-5 xl:grid-cols-[1.08fr_420px_1.2fr]">
                  <div style={steelCardStyle()}>
                    <div style={darkHeaderStyle(RED)}>
                      <div className="flex items-center justify-between gap-3">
                        <div className="flex items-center gap-3">
                          <span
                            className="inline-block h-5 w-5 rounded-[4px]"
                            style={{ background: RED }}
                          />
                          <div className="text-[18px] font-black uppercase tracking-[0.06em]">
                            Fighter
                          </div>
                        </div>

                        <span style={badgeStyle("neutral")}>Context</span>
                      </div>
                    </div>

                    <div style={darkSectionBodyStyle()}>
                      <div className="text-[30px] leading-none font-black text-[#ff5a0a] md:text-[40px]">
                        {fullName}
                      </div>

                      <div className="mt-2 text-[16px] font-extrabold text-white/70">
                        {row.gym_input || row.fp_gym || "—"}
                      </div>

                      <div className="mt-4 text-[15px] font-extrabold text-white/88">
                        FP/VA: {row.va_nummer || "—"}
                      </div>

                      <div className="mt-4 flex flex-wrap gap-3">
                        <div className="flex items-center gap-2 text-sm font-black text-white/75">
                          <span>Naam:</span>
                          <span style={badgeStyle(naamMatch ? "ok" : "warn")}>
                            {statusFromBool(naamMatch, "JA", "CHECK")}
                          </span>
                        </div>

                        <div className="flex items-center gap-2 text-sm font-black text-white/75">
                          <span>Geb.:</span>
                          <span style={badgeStyle(dobMatch ? "ok" : "warn")}>
                            {statusFromBool(dobMatch, "JA", "CHECK")}
                          </span>
                        </div>

                        <div className="flex items-center gap-2 text-sm font-black text-white/75">
                          <span>Gym:</span>
                          <span style={badgeStyle(gymMatch ? "ok" : "warn")}>
                            {statusFromBool(gymMatch, "JA", "CHECK")}
                          </span>
                        </div>
                      </div>

                      <div className="mt-6 grid grid-cols-1 gap-3 md:grid-cols-2">
                        <div className="text-[15px] font-extrabold text-white/85">
                          <div>
                            Geboortedatum:{" "}
                            {row.geboortedatum_input
                              ? fmtDate(row.geboortedatum_input)
                              : "—"}
                          </div>
                          <div className="mt-2">Geslacht: {row.geslacht ?? "—"}</div>
                          <div className="mt-2">
                            Discipline: {row.discipline ?? "—"}
                          </div>
                          <div className="mt-2">Klasse: {row.klasse ?? "—"}</div>
                        </div>

                        <div className="text-[15px] font-extrabold text-white/85">
                          <div>Gewicht: {fmtKg(row.gewicht)}</div>
                          <div className="mt-2">
                            Licentie:{" "}
                            <span
                              style={badgeStyle(
                                licentieJaNee === "Ja"
                                  ? "ok"
                                  : licentieJaNee === "Nee"
                                  ? "bad"
                                  : "neutral"
                              )}
                            >
                              {licentieJaNee}
                            </span>
                          </div>
                          <div className="mt-2">
                            Start verbod:{" "}
                            <span
                              style={badgeStyle(
                                startVerbodText === "Nee"
                                  ? "ok"
                                  : startVerbodText === "Ja"
                                  ? "bad"
                                  : "warn"
                              )}
                            >
                              {startVerbodText}
                            </span>
                          </div>
                          <div className="mt-2">
                            Keurmerk:{" "}
                            <span style={badgeStyle(keurmerk ? "ok" : "neutral")}>
                              {keurmerk ? "GELDIG" : "ONBEKEND"}
                            </span>
                          </div>
                        </div>
                      </div>

                      <div
                        className="mt-6 rounded-[16px] p-4"
                        style={{
                          border: "2px solid rgba(255,255,255,0.08)",
                          background:
                            "linear-gradient(180deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 100%)",
                          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.08)",
                        }}
                      >
                        <div className="text-[15px] font-black text-white/70">
                          Extra / nulmeting
                        </div>
                        <div className="mt-2 text-[15px] font-extrabold text-white/88">
                          {row.nulmeting_opmerking?.trim() || "—"}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-col gap-4">
                    <div
                      className="mx-auto"
                      style={{
                        width: "100%",
                        maxWidth: 350,
                        aspectRatio: "1 / 1",
                        borderRadius: "999px",
                        padding: 14,
                        background:
                          "linear-gradient(180deg, #cfcfcf 0%, #8b8b8b 38%, #111111 100%)",
                        boxShadow:
                          "0 18px 40px rgba(0,0,0,0.35), inset 0 2px 0 rgba(255,255,255,0.45)",
                      }}
                    >
                      <div
                        style={{
                          width: "100%",
                          height: "100%",
                          borderRadius: "999px",
                          position: "relative",
                          overflow: "hidden",
                          border: "8px solid rgba(0,0,0,0.5)",
                          background:
                            "radial-gradient(circle at 50% 42%, rgba(255,77,0,0.26), transparent 38%), linear-gradient(180deg, #2b2e35 0%, #0b0c0f 100%)",
                          boxShadow:
                            "inset 0 1px 0 rgba(255,255,255,0.18), inset 0 0 0 2px rgba(255,255,255,0.08)",
                        }}
                      >
                        <Image
                          src="/branding/fightsupport/fighter-shield.png"
                          alt="FightSupport"
                          fill
                          priority
                          style={{ objectFit: "cover", transform: "scale(1.04)" }}
                        />
                      </div>
                    </div>

                    <div style={steelCardStyle()}>
                      <div style={darkHeaderStyle()}>
                        <div className="flex items-center gap-3">
                          <span
                            className="inline-block h-5 w-5 rounded-[4px]"
                            style={{ background: NVB_ORANGE }}
                          />
                          <div className="text-[18px] font-black uppercase tracking-[0.06em]">
                            Fighter details
                          </div>
                        </div>
                      </div>

                      <div style={sectionBodyStyle()}>
                        <FieldRow label="Naam" value={fullName} />
                        <FieldRow label="Klasse" value={row.klasse ?? "—"} />
                        <FieldRow label="Gewicht" value={fmtKg(row.gewicht)} />
                        <FieldRow label="Geslacht" value={row.geslacht ?? "—"} />
                        <FieldRow label="Record" value={recordStr} />
                        <FieldRow label="Uitslagen" value={`${uitslagenRows.length}x`} />
                        <FieldRow
                          label="Laatste partij"
                          value={
                            row.laatste_partij_datum
                              ? fmtDate(row.laatste_partij_datum)
                              : "—"
                          }
                        />
                      </div>
                    </div>
                  </div>

                  <UitslagenTable rows={uitslagenRows} />
                </div>

                <div className="mt-6 grid grid-cols-1 gap-5 xl:grid-cols-2">
                  <MeldingenList
                    title="Meldingen"
                    iconColor={NVB_ORANGE}
                    lines={meldingLines}
                    emptyText="Nog geen meldingen opgeslagen."
                  />

                  <MeldingenList
                    title="Verschillen"
                    iconColor={BLUE}
                    lines={verschillenLines}
                    emptyText="Nog geen verschillen opgeslagen."
                  />
                </div>

                <div className="mt-6 grid grid-cols-1 gap-5 xl:grid-cols-2">
                  <ZebraObjectTable
                    title="Keurmerk detail"
                    rows={[
                      {
                        key: "Status",
                        value: keurmerk ? "Geldig" : "Onbekend / controle nodig",
                      },
                      {
                        key: "Input gym",
                        value: row.gym_input ?? "—",
                      },
                      {
                        key: "FightPassport gym",
                        value: row.fp_gym ?? "—",
                      },
                      {
                        key: "DB match sportschool",
                        value: keurmerkInfo.matchedGym ?? "—",
                      },
                      {
                        key: "Bron gym",
                        value: keurmerkInfo.bronGym ?? "—",
                      },
                      {
                        key: "Melding",
                        value: keurmerkInfo.reason ?? "—",
                      },
                    ]}
                    emptyText="Geen keurmerkdata."
                  />

                  <ZebraObjectTable
                    title="Extra"
                    rows={cleanedExtraRows}
                    emptyText="Geen overige extra velden."
                  />
                </div>

                <div className="mt-6 grid grid-cols-1 gap-5 xl:grid-cols-2">
                  <div style={darkCardShellStyle()}>
                    <div style={darkHeaderStyle()}>
                      <div className="flex items-center gap-3">
                        <span
                          className="inline-block h-5 w-5 rounded-[4px]"
                          style={{ background: RED }}
                        />
                        <div className="text-[18px] font-black uppercase tracking-[0.06em]">
                          Matchmaker invoer
                        </div>
                      </div>
                    </div>

                    <div style={darkSectionBodyStyle()}>
                      <DarkFieldRow
                        label="Inschrijving ID"
                        value={row.inschrijving_id ?? "—"}
                      />
                      <DarkFieldRow label="Row nr" value={row.row_nr ?? "—"} />
                      <DarkFieldRow label="Naam input" value={row.naam_input ?? "—"} />
                      <DarkFieldRow label="Gym input" value={row.gym_input ?? "—"} />
                      <DarkFieldRow
                        label="Geboortedatum input"
                        value={
                          row.geboortedatum_input
                            ? fmtDate(row.geboortedatum_input)
                            : "—"
                        }
                      />
                      <DarkFieldRow label="Gewicht" value={fmtKg(row.gewicht)} />
                      <DarkFieldRow label="VA nummer" value={row.va_nummer ?? "—"} />
                    </div>
                  </div>

                  <div style={darkCardShellStyle()}>
                    <div style={darkHeaderStyle()}>
                      <div className="flex items-center gap-3">
                        <span
                          className="inline-block h-5 w-5 rounded-[4px]"
                          style={{ background: BLUE }}
                        />
                        <div className="text-[18px] font-black uppercase tracking-[0.06em]">
                          FightPassport gevonden
                        </div>
                      </div>
                    </div>

                    <div style={darkSectionBodyStyle()}>
                      <DarkFieldRow label="FP naam" value={row.fp_naam ?? "—"} />
                      <DarkFieldRow
                        label="FP geboortedatum"
                        value={
                          row.fp_geboortedatum
                            ? fmtDate(row.fp_geboortedatum)
                            : "—"
                        }
                      />
                      <DarkFieldRow label="FP gym" value={row.fp_gym ?? "—"} />
                      <DarkFieldRow label="FP klasse" value={row.fp_klasse ?? "—"} />
                      <DarkFieldRow label="Record" value={recordStr} />
                      <DarkFieldRow
                        label="Laatste partij"
                        value={
                          row.laatste_partij_datum
                            ? fmtDate(row.laatste_partij_datum)
                            : "—"
                        }
                      />
                    </div>
                  </div>
                </div>

                <div className="mt-5 text-center text-xs font-black uppercase tracking-[0.12em] text-zinc-600">
                  Data bron: matchmaker_fighter_context + matchmaker_uitslagen_raw •
                  matchmaking: {matchmakingId} • fighter ref: {fighterContextId}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}